mapper.update:
UPDATE goods
name = #{name}, wholesale_price = #{wholesalePrice}, retail_price = #{retailPrice}, vendor_id = #{vendorId}, update_time = CURRENT_TIMESTAMP
WHERE barcode = #{barcode}

mapper.select:
SELECT g.*, f.name AS vendor_name FROM goods g LEFT JOIN factory f ON g.vendor_id = f.id
AND g.barcode LIKE '%' || #{barcode} || '%'
AND g.name LIKE '%' || #{name} || '%'
AND g.vendor_id = #{vendorId}
ORDER BY g.id DESC LIMIT #{limit} OFFSET #{offset}
